SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(6*10^9);Alarm(600);tt:=Cputime();root:="work/deg10/continuation_20261031b/M3N18/";AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");Attach("work/deg10/continuation_20261029/deps/fast_hecke_11.m");Attach(root cat "inputs/fast_full_aut_hash_m3_18_root.m");k:=GF(p);X:=MDX11(3,18,k);C:=Curve(X);FF:=FunctionField(C);F,mp:=AlgorithmicFunctionField(FF);assert Genus(F)eq 10;B:=BaseField(F);u:=F!B.1;du:=Differential(u);E:=EllipticCurve(X`_E);P:=E!X`_P;Q:=E!X`_Q;T:=9*Q;assert 2*T eq E!0 and T ne E!0;a1,a2,a3,a4,a6:=Explode(aInvariants(E));rr:=T[1];AA:=a2+a1^2/4;BB:=a4+a1*a3/2;A:=3*rr+AA;BB2:=3*rr^2+2*AA*rr+BB;EG:=EllipticCurve([FF!0,-2*A,FF!0,A^2-4*BB2,FF!0]);
function Phi(R)xx:=R[1]-rr;yy:=R[2]+(a1*R[1]+a3)/2;return EG![xx+A+BB2/xx,yy*(1-BB2/xx^2)];end function;
PP:=Phi(P);QQ:=2*Phi(Q)+(EG![0,0]);assert 3*PP eq EG!0 and 18*QQ eq EG!0 and 9*QQ ne EG!0 and 6*QQ ne EG!0;qf,tf:=Explode(M3EighteenRootNormalizedPair(EG,PP,QQ));XY:=[mp(qf)-1,mp(tf)*mp(qf)/(mp(qf)-1)];
function Sub(f)ff:=f@@mp;nn:=Numerator(ff);dd:=Denominator(ff);args:=Rank(Parent(nn))eq 3 select XY cat[F!1]else XY;return Evaluate(nn,args)/Evaluate(dd,args);end function;
bm:=hom<B->F|Sub(F!B.1)>;tau:=hom<F->F|bm,Sub(F.1)>;assert tau(tau(F.1))eq F.1 and tau(tau(u))eq u;VO,om:=SpaceOfHolomorphicDifferentials(F);bs:=[om(v):v in Basis(VO)];bfs:=[v/du:v in bs];factor:=Differential(tau(u));TM:=Matrix(k,[Eltseq((tau(f)*factor)@@om):f in bfs]);assert TM^2 eq 1;function ER(f)return [[Integers()!c:c in Coefficients(Numerator(f))],[Integers()!c:c in Coefficients(Denominator(f))]];end function;function EF(f)return [ER(c):c in Eltseq(F!f)];end function;
function Units(E,P,Q)ai:=aInvariants(E);fs:=[ai[3],ai[1]^3-27*ai[3]];for j in[1..9]do for b in[0..2]do R:=j*Q+b*P;fs cat:=[R[1],R[2]];end for;R:=j*Q;S:=R+P;Append(~fs,R[1]-S[1]);end for;return fs;end function;
cs:=Cusps(X);fs:=Units(E,P,Q);sigs:=[[Valuation(f,c):f in fs]:c in cs];ordered:=Sort(sigs);g:=eval Read(root cat "paired_p"cat IntegerToString(p)cat"_group_data.m");assert ordered eq g[2];cs:=[cs[Index(sigs,sg)]:sg in ordered];acs:=[];for c in cs do ps,es:=Support(FunctionFieldDivisor(Divisor(c)));assert #ps eq 1;Append(~acs,ps[1]);end for;per:=[Index(ordered,[Valuation(tau(mp(f)),c):f in fs]):c in acs];assert Seqset(per)eq{1..24}and &and[per[per[i]]eq i:i in[1..24]];Write(root cat "tau_cusp_permutation_p"cat IntegerToString(p)cat".m",Sprint([*p,per*]):Overwrite:=true);print "D31B_M318_TAU_CUSP_PERMUTATION_COMPLETE",p,per,Cputime(tt);quit;
